BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — Evaluate qualitative factors when aggregate uncorrected misstatements approach materiality
(1, 'Misstatements and Control Deficiencies', 'During the audit of Granite Peak Industries, the auditor identifies $38,000 in aggregate uncorrected misstatements against overall materiality of $45,000. Management refuses to correct the remaining items. While each individual misstatement relates to a different account, the auditor notes that $22,000 of the aggregate involves revenue overstatements that could mask a declining trend in core operations. The auditor should:', '["Issue an unmodified opinion because the aggregate does not exceed materiality", "Request management to make additional disclosures about the declining revenue trend", "Evaluate whether the qualitative nature of the misstatements renders them material despite being below the quantitative threshold", "Issue a qualified opinion because the aggregate exceeds performance materiality"]'::jsonb, 2, 'Under AU-C 450.11, the auditor must evaluate whether uncorrected misstatements are material individually or in the aggregate, considering both quantitative and qualitative factors. Even when the aggregate falls below the quantitative threshold, the nature of misstatements—such as masking revenue trends—may render them material. Choice A is incorrect because it ignores the qualitative assessment required by the standard.', 'hard', 4),

-- Q2: hard / L3 — Analyze management bias indicators in misstatement patterns
(1, 'Misstatements and Control Deficiencies', 'While auditing Clearwater Technologies, the engagement team observes that all six uncorrected misstatements identified during testing result in income overstatements, with a combined effect of $28,000 against materiality of $60,000. Although the aggregate is well below materiality, the consistent direction of these misstatements most likely indicates the auditor should:', '["Accept the misstatements as immaterial since the aggregate is less than 50% of materiality", "Consider whether the pattern indicates possible management bias in the financial statements", "Require management to correct all six misstatements regardless of materiality", "Communicate the pattern as a material weakness to those charged with governance"]'::jsonb, 1, 'Under AU-C 450.A17, the auditor should consider whether the accumulation of misstatements with a consistent directional pattern—all overstating income—may indicate management bias. This assessment goes beyond quantitative evaluation. Choice A is incorrect because the quantitative amount alone does not eliminate the need to evaluate bias indicators, which could affect the auditor''s overall assessment of the financial statements.', 'hard', 3),

-- Q3: easy / L1 — Definition of clearly trivial misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what does the term ''clearly trivial'' mean in the context of audit misstatements?', '["Misstatements that are below the performance materiality threshold", "Misstatements that management has agreed to correct before year-end", "Misstatements that do not affect the income statement", "Misstatements that are inconsequential both individually and in the aggregate"]'::jsonb, 3, 'Under AU-C 450.A2, misstatements are clearly trivial when they are inconsequential whether taken individually or in the aggregate, considering size, nature, and circumstances. The auditor need not accumulate clearly trivial misstatements. Choice A is incorrect because clearly trivial is a lower threshold than performance materiality—many immaterial items are not clearly trivial.', 'easy', 1),

-- Q4: medium / L2 — Apply the clearly trivial posting threshold to accumulate misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgeline Services Corp., the engagement team sets materiality at $100,000 and performance materiality at $75,000. The auditor establishes a clearly trivial threshold of $4,500. The team identifies three misstatements: $3,800, $5,200, and $12,000. Under AU-C 450, which misstatements must the auditor accumulate?', '["The $5,200 and $12,000 misstatements, since they exceed the clearly trivial threshold", "All three misstatements, since any identified misstatement must be accumulated", "Only the $12,000 misstatement, since the others are below performance materiality", "Only the $5,200 misstatement, since it is the only one between clearly trivial and performance materiality"]'::jsonb, 0, 'Under AU-C 450.05, the auditor must accumulate all identified misstatements during the audit except those that are clearly trivial. Since $3,800 is below the $4,500 clearly trivial threshold, it need not be accumulated. The $5,200 and $12,000 both exceed the threshold and must be accumulated. Choice B is incorrect because AU-C 450 explicitly permits the auditor to disregard clearly trivial misstatements.', 'medium', 2),

-- Q5: medium / L3 — Analyze how fraud vs. error misstatements differ in auditor response
(1, 'Misstatements and Control Deficiencies', 'Maple Grove Enterprises has two uncorrected misstatements, each totaling $6,000. The first arose from a clerical posting error in accounts payable, while the second resulted from the controller intentionally reclassifying a personal expense as a business expense. Both are below materiality. The auditor should analyze these misstatements differently because:', '["Fraud-related misstatements require immediate communication to law enforcement", "Intentional misstatements may indicate additional undetected misstatements and affect risk assessment", "Error-based misstatements must be corrected while fraud-based misstatements are reported only", "The clerical error affects the opinion while the fraud does not"]'::jsonb, 1, 'Under AU-C 240.35, when a misstatement results from fraud—even if immaterial—the auditor must evaluate its implications for the audit, including whether it indicates a risk of additional misstatements. An intentional misstatement signals potential management integrity issues that may warrant revised risk assessments. Choice A is incorrect because AU-C 240 does not require reporting to law enforcement; the auditor''s primary obligation is to those charged with governance.', 'medium', 3),

-- Q6: medium / L3 — Analyze aggregation of multiple deficiencies within one process
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sentinel Financial Group, the auditor identifies three control deficiencies in the loan origination process: incomplete documentation of credit approvals, lack of segregation between loan officers and disbursement, and no independent review of loan-to-value ratios. Individually, each is classified as a deficiency. The auditor should analyze these deficiencies together because:', '["AU-C 265 requires all deficiencies in a single process to be reported as a single finding", "Individual deficiencies in the same process automatically constitute a material weakness", "Aggregation is only required when deficiencies span multiple financial statement assertions", "The combination of deficiencies affecting the same process may collectively represent a significant deficiency or material weakness"]'::jsonb, 3, 'Under AU-C 265.A12, the auditor must consider whether multiple control deficiencies affecting the same significant account or process, when taken together, constitute a significant deficiency or material weakness. Deficiencies may interact to increase the overall risk beyond what each presents individually. Choice B is incorrect because aggregation requires the auditor''s judgment about combined severity, not an automatic classification.', 'medium', 3),

-- Q7: medium / L2 — Apply AU-C 450 management representation letter requirement for uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Atlas Manufacturing has three uncorrected misstatements totaling $14,500, which are below materiality of $50,000. The auditor prepares a summary of these misstatements to attach to the management representation letter. Under AU-C 450, the management representation letter should include:', '["Management''s belief that the effects of uncorrected misstatements are immaterial to the financial statements as a whole", "Management''s acknowledgment that all misstatements have been corrected", "A commitment by management to correct all uncorrected misstatements in the subsequent period", "Management''s assertion that no additional misstatements exist beyond those identified"]'::jsonb, 0, 'Under AU-C 450.14, the auditor must request a written representation from management that it believes the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole. A summary of such items is included with or attached to the representation letter. Choice C is incorrect because the standard does not require management to commit to future correction of immaterial misstatements.', 'medium', 2),

-- Q8: medium / L3 — Analyze pervasive vs. non-pervasive material misstatements and opinion type
(1, 'Misstatements and Control Deficiencies', 'Pinnacle Resources Inc. has a $320,000 uncorrected misstatement in inventory valuation, which exceeds overall materiality of $200,000. The misstatement affects only the inventory and cost of goods sold line items and does not impact other accounts or disclosures. The auditor should analyze this situation to determine whether to issue:', '["An adverse opinion because the misstatement exceeds materiality", "A disclaimer of opinion because the scope of the misstatement cannot be determined", "A qualified opinion because the misstatement is material but confined to specific accounts", "An unmodified opinion with an emphasis-of-matter paragraph"]'::jsonb, 2, 'Under AU-C 705.08, when the auditor concludes that misstatements are material but not pervasive to the financial statements, a qualified opinion is appropriate. A misstatement is pervasive when it affects multiple elements, accounts, or represents a substantial proportion of the financials. Choice A is incorrect because an adverse opinion is warranted only when misstatements are both material and pervasive to the financial statements as a whole.', 'medium', 3),

-- Q9: hard / L4 — Evaluate whether prior-year uncorrected misstatements affect current-year opinion
(1, 'Misstatements and Control Deficiencies', 'During the 2025 audit of Horizon Data Systems, the auditor notes that $47,000 in prior-year uncorrected misstatements related to depreciation continue to affect the 2025 financial statements through overstated asset carrying amounts. Current-year materiality is $55,000, and the auditor identifies $18,000 in new current-year misstatements. The prior-year misstatements were evaluated as immaterial last year. The auditor should evaluate whether:', '["The prior-year misstatements can be ignored because they were previously evaluated as immaterial", "The combined effect of prior-year carryforward misstatements and current-year misstatements may be material to the current financial statements", "Only the $18,000 in current-year misstatements should be considered in the aggregate assessment", "The prior-year misstatements must be restated before the current audit can be completed"]'::jsonb, 1, 'Under AU-C 450.A8, the auditor must consider the effect of uncorrected misstatements from prior periods that carry forward into the current year. These turnaround effects—such as ongoing overstatement from underdepreciation—combine with current-year misstatements in the aggregate assessment. Choice A is incorrect because a misstatement deemed immaterial in one year may become material when combined with current-year items or when it accumulates over multiple periods.', 'hard', 4),

-- Q10: hard / L4 — Evaluate communication when governance is involved in the control deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Beacon Holdings LLC, the auditor identifies a material weakness in the override of procurement controls. Investigation reveals that the board chairperson personally approved $450,000 in payments to a related-party vendor without following the entity''s competitive bidding policy. The board chairperson also serves as the primary recipient of AU-C 265 communications. The auditor should evaluate the most appropriate course of action, which is to:', '["Communicate the material weakness directly to the full board excluding the chairperson", "Report the finding only to management and note it in the audit documentation", "Consider the implications for the overall audit strategy and communicate to an appropriate level of governance not involved in the deficiency", "Withdraw from the engagement because the governance structure is compromised"]'::jsonb, 2, 'Under AU-C 265.A28 and AU-C 260.09, when those charged with governance are directly involved in a control deficiency, the auditor must consider the implications for the audit and communicate to a level of authority not involved in the deficiency, such as an independent audit committee or the full board. Choice D is incorrect because withdrawal is a last resort; the auditor should first attempt to identify an appropriate communication channel within the governance structure.', 'hard', 4),

-- Q11: medium / L3 — Analyze how transaction magnitude affects control deficiency severity
(1, 'Misstatements and Control Deficiencies', 'An auditor at Lakeview CPA Firm identifies identical control deficiencies—lack of independent review—in two processes at Cedar Creek Manufacturing: petty cash disbursements ($2,000 monthly volume) and revenue recognition for long-term contracts ($8 million annually). The auditor should analyze these deficiencies differently because:', '["Petty cash deficiencies are always immaterial and need not be reported", "Revenue recognition deficiencies are automatically classified as material weaknesses", "Only deficiencies involving financial statement line items require classification", "The magnitude of transactions processed by the control affects the potential for material misstatement"]'::jsonb, 3, 'Under AU-C 265.A9, the severity of a control deficiency depends on the magnitude of the potential misstatement resulting from the deficiency, not just the deficiency itself. A missing review over $8 million in revenue poses far greater risk than the same deficiency over $2,000 in petty cash. Choice B is incorrect because no deficiency type is automatically classified as a material weakness—the auditor must assess both likelihood and magnitude.', 'medium', 3),

-- Q12: medium / L2 — Apply AU-C 450 documentation requirements for misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Northwind Technologies, the engagement partner reviews the documentation for misstatement evaluation. Under AU-C 450, the audit documentation must include:', '["The amount below which misstatements are considered clearly trivial, the accumulated uncorrected misstatements, and the auditor''s conclusion on their materiality", "Only those misstatements that were corrected by management during the audit", "A description of why each identified misstatement was not corrected by management", "Management''s oral acknowledgment that all identified misstatements are immaterial"]'::jsonb, 0, 'Under AU-C 450.15, the auditor must document the clearly trivial threshold, all misstatements accumulated during the audit, the auditor''s conclusion on whether uncorrected misstatements are material, and the basis for that conclusion. Choice B is incorrect because documentation must include uncorrected misstatements and the evaluation process, not just corrected items.', 'medium', 2),

-- Q13: medium / L2 — Apply the communication timeline for significant deficiency reporting
(1, 'Misstatements and Control Deficiencies', 'On March 15, 2026, Evergreen Auditing completes the audit of Cascade Valley Corp. for the year ended December 31, 2025. The auditor identified two significant deficiencies during fieldwork completed on February 20, 2026. Under AU-C 265, the written communication of significant deficiencies to those charged with governance must be made:', '["Within 30 days after the identification of the deficiencies during fieldwork", "No later than 60 days following the release of the auditor''s report", "Before the financial statements are issued to prevent reliance on deficient controls", "Concurrently with the issuance of the auditor''s report on the financial statements"]'::jsonb, 1, 'Under AU-C 265.13, the auditor''s written communication of significant deficiencies and material weaknesses should be made no later than 60 days following the release of the auditor''s report. This allows the auditor to finalize the evaluation before communicating. Choice D is incorrect because simultaneous issuance is not required—the standard provides a 60-day window after the report release date.', 'medium', 2),

-- Q14: medium / L3 — Analyze design deficiency vs. operating deficiency classification
(1, 'Misstatements and Control Deficiencies', 'Redwood Consulting discovers that Summit Logistics has a properly designed control requiring dual authorization for wire transfers over $10,000. However, testing reveals that in 12 of 40 sampled transactions, only one authorization was obtained. The auditor should analyze this finding as:', '["A design deficiency because the control is not preventing unauthorized wire transfers", "A material weakness because the failure rate exceeds 25% of the sample", "A significant deficiency only if one of the unauthorized transfers resulted in a loss", "An operating deficiency because the control exists but is not being executed as designed"]'::jsonb, 3, 'Under AU-C 265.A4, an operating deficiency exists when a properly designed control does not operate effectively or when the person performing the control lacks the authority or competence to do so. Since Summit Logistics designed the dual-authorization control correctly but personnel failed to execute it, this is an operating deficiency. Choice A is incorrect because a design deficiency would mean the control, even if operating as designed, could not prevent or detect misstatements.', 'medium', 3),

-- Q15: easy / L1 — Definition of a control deficiency
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what is a control deficiency in internal control over financial reporting?', '["A condition in which a control''s design or operation does not allow management or employees to prevent or detect misstatements on a timely basis", "A fraud committed by an employee that the entity''s controls failed to prevent", "Any error in the financial statements that results from the absence of a specific control", "A situation where external auditors identify a misstatement exceeding materiality"]'::jsonb, 0, 'Under AU-C 265.07, a control deficiency exists when the design or operation of a control does not allow management or employees, in the normal course of performing their assigned functions, to prevent or detect and correct misstatements on a timely basis. Choice B is incorrect because fraud itself is not a control deficiency—the deficiency is the underlying control weakness that permitted the fraud to occur.', 'easy', 1),

-- Q16: medium / L3 — Analyze how IT general control deficiencies affect application control reliability
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pacific Coast Distributors, the auditor determines that the automated three-way match control in accounts payable is operating effectively. However, the auditor also discovers that IT general controls over program change management are deficient, meaning unauthorized changes could be made to the matching algorithm. The auditor should analyze this finding to determine whether:', '["The accounts payable control can still be relied upon since it tested effectively during the sample period", "The IT general control deficiency undermines the reliability of the automated application control throughout the period", "Only the IT general control deficiency needs to be reported, not the application control", "The automated control should be reclassified from preventive to detective"]'::jsonb, 1, 'Under AU-C 315.A140, IT general controls support the continued proper functioning of application controls. When program change management controls are deficient, the auditor cannot rely on automated controls operating consistently throughout the audit period, even if point-in-time testing showed effective operation. Choice A is incorrect because effective sample results do not compensate for the risk that the control logic could have been altered without authorization during the period.', 'medium', 3),

-- Q17: medium / L2 — Apply communication requirements for deficiencies below significant level
(1, 'Misstatements and Control Deficiencies', 'While auditing Birchwood Financial Services, the auditor identifies several control deficiencies that do not individually or in combination rise to the level of a significant deficiency. Under AU-C 265, the auditor should communicate these deficiencies to:', '["Those charged with governance in writing within 60 days of the report", "No one, because only significant deficiencies and material weaknesses require communication", "Management, and the auditor should determine whether the communication should be in writing", "The audit committee only if management fails to remediate them within 90 days"]'::jsonb, 2, 'Under AU-C 265.12, the auditor should communicate to management control deficiencies that are not significant deficiencies or material weaknesses but are of sufficient importance to merit management''s attention. The auditor determines whether to make this communication in writing or orally. Choice B is incorrect because AU-C 265 does require communication of other noteworthy deficiencies to management, even though only significant deficiencies and material weaknesses must be communicated to governance.', 'medium', 2),

-- Q18: easy / L1 — Definition of performance materiality
(1, 'Misstatements and Control Deficiencies', 'What is the primary purpose of setting performance materiality at an amount less than overall materiality?', '["To establish the threshold for issuing a qualified opinion on the financial statements", "To set the maximum amount of any single misstatement the auditor will accept", "To determine the clearly trivial amount below which misstatements need not be accumulated", "To reduce the probability that the aggregate of uncorrected and undetected misstatements exceeds materiality"]'::jsonb, 3, 'Under AU-C 320.09, performance materiality is set below overall materiality to reduce to an appropriately low level the probability that the aggregate of uncorrected and undetected misstatements exceeds materiality for the financial statements as a whole. It acts as a planning buffer. Choice A is incorrect because the opinion threshold is based on overall materiality, not performance materiality.', 'easy', 1),

-- Q19: medium / L3 — Analyze the effect of compensating control failure on deficiency reclassification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Heritage Properties Inc., the auditor initially classified a deficiency in the automated lease payment calculation as a significant deficiency because a manual reconciliation by the controller served as a compensating control. Subsequent testing reveals the controller performed the reconciliation for only two of twelve months. The auditor should analyze whether:', '["The automated control deficiency should be reclassified to a material weakness given the compensating control''s ineffectiveness", "The original classification remains appropriate because the compensating control was designed properly", "The controller''s reconciliation represents a separate deficiency unrelated to the automated control", "The deficiency should be downgraded because partial operation provides some level of mitigation"]'::jsonb, 0, 'Under AU-C 265.A11, compensating controls can mitigate the severity of a deficiency, but only if they operate effectively. When the compensating control—the monthly reconciliation—operated in only two of twelve months, it cannot reliably reduce the severity of the primary deficiency. The auditor must reassess the original classification. Choice D is incorrect because sporadic operation of a compensating control does not provide sufficient mitigation to lower a deficiency''s severity classification.', 'medium', 3),

-- Q20: hard / L4 — Evaluate whether a remediated deficiency must still be communicated
(1, 'Misstatements and Control Deficiencies', 'Cornerstone Advisors is auditing Apex Industrial Corp. for the year ended December 31, 2025. In September 2025, the auditor identified a material weakness in the revenue cutoff process. Management implemented a new automated cutoff control in October 2025 and provides evidence that the control operated effectively for the final quarter. Management also demonstrates through detailed testing that no revenue cutoff misstatements occurred during the nine months the weakness existed. The auditor should:', '["Reclassify the deficiency as a significant deficiency because it was remediated before year-end", "Omit the deficiency from the written communication because management remediated it and proved no misstatement occurred", "Communicate the material weakness in writing because it existed during the period under audit, regardless of subsequent remediation", "Delay the communication until the next audit to verify the new control''s continued effectiveness"]'::jsonb, 2, 'Under AU-C 265.A18, the auditor should communicate material weaknesses that existed during the audit period, even if they were subsequently remediated. The fact that no actual misstatement resulted does not change the severity classification—the deficiency''s potential impact during the period it existed determines classification. Choice B is incorrect because remediation and absence of actual misstatement do not relieve the auditor of the obligation to communicate material weaknesses that existed during the period.', 'hard', 4),

-- Q21: medium / L2 — Apply individual vs. aggregate evaluation of uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Trident Manufacturing, the auditor identifies five uncorrected misstatements: $8,000 in inventory, $6,500 in accounts payable, $9,200 in depreciation, $4,300 in prepaid expenses, and $7,000 in accrued liabilities. Overall materiality is $50,000. Each misstatement is individually immaterial. Under AU-C 450, the auditor must:', '["Accept all misstatements without further evaluation since each is individually immaterial", "Evaluate the aggregate amount of $35,000 to determine whether it is material to the financial statements", "Require management to correct any misstatement exceeding $10,000", "Project each misstatement to the population before aggregating"]'::jsonb, 1, 'Under AU-C 450.11, the auditor must evaluate whether uncorrected misstatements are material, individually or in the aggregate. Even though each misstatement is below materiality, their combined $35,000 represents 70% of materiality, requiring the auditor to assess the aggregate effect. Choice A is incorrect because individual immateriality does not eliminate the need for aggregate evaluation, which is a required step under the standard.', 'medium', 2),

-- Q22: easy / L1 — Responsibility for correcting identified misstatements
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, who is primarily responsible for correcting misstatements identified during an audit?', '["Management of the entity being audited", "The external auditor who identified the misstatements", "The audit committee or those charged with governance", "The engagement quality reviewer"]'::jsonb, 0, 'Under AU-C 450.08, the auditor should communicate all misstatements accumulated during the audit with management and request that management correct those misstatements. Management bears primary responsibility for the preparation and fair presentation of the financial statements, including correcting errors. Choice B is incorrect because the auditor''s role is to identify and communicate misstatements, not to correct the entity''s financial records.', 'easy', 1),

-- Q23: hard / L4 — Evaluate management self-assessment vs. auditor independent deficiency evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Metro Systems Inc., management presents its own internal control assessment that classifies a deficiency in the journal entry approval process as a minor deficiency. Management cites three years of clean audit opinions and no historical misstatements from the process. The auditor''s independent evaluation, however, determines that the deficiency permits unauthorized journal entries affecting any financial statement account. Based on these competing assessments, the auditor should:', '["Defer to management''s classification because they have greater knowledge of the entity''s operations and history", "Accept management''s classification if the deficiency has not resulted in a material misstatement", "Negotiate a compromise classification between management''s and the auditor''s assessments", "Apply the auditor''s own professional judgment to classify the deficiency independently of management''s assessment"]'::jsonb, 3, 'Under AU-C 265.A7, the evaluation of control deficiency severity is the auditor''s professional responsibility and must be based on the auditor''s independent judgment. Management''s self-assessment does not override the auditor''s evaluation. A deficiency permitting unauthorized journal entries affecting all accounts has high potential for material misstatement regardless of historical outcomes. Choice A is incorrect because AU-C 265 does not allow the auditor to defer to management''s own deficiency classification.', 'hard', 4),

-- Q24: easy / L1 — Definition of an operating deficiency
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, what is an operating deficiency in internal control?', '["A control that is missing from the entity''s control environment entirely", "A control that is not designed to meet a specific control objective", "A properly designed control that does not operate effectively as intended", "A control that is too costly relative to the risk it addresses"]'::jsonb, 2, 'Under AU-C 265.A4, an operating deficiency exists when a properly designed control does not operate effectively, or when the person performing the control does not possess the necessary authority or competence to perform the control effectively. The control exists by design but fails in practice. Choice A is incorrect because a missing control represents a design deficiency, not an operating deficiency.', 'easy', 1),

-- Q25: easy / L1 — Three categories of misstatements under AU-C 450
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, which of the following are the three categories of misstatements an auditor may identify?', '["Known, likely, and possible misstatements", "Factual, judgmental, and projected misstatements", "Material, immaterial, and trivial misstatements", "Quantitative, qualitative, and pervasive misstatements"]'::jsonb, 1, 'Under AU-C 450.A1, misstatements are classified as factual (misstatements about which there is no doubt), judgmental (differences arising from management''s judgments about estimates that the auditor considers unreasonable), and projected (the auditor''s best estimate of misstatements in populations based on audit sampling). Choice A is incorrect because known, likely, and possible is an older terminology framework not used in AU-C 450.', 'easy', 1),

-- Q26: easy / L1 — Tolerable misstatement definition in audit sampling
(1, 'Misstatements and Control Deficiencies', 'In the context of audit sampling, what does tolerable misstatement represent?', '["The maximum misstatement in a population that the auditor is willing to accept", "The total amount of misstatements the auditor expects to find in a population", "The threshold below which all misstatements are considered clearly trivial", "The amount of misstatement that would cause a qualified opinion"]'::jsonb, 0, 'Under AU-C 530.A3, tolerable misstatement is a monetary amount set by the auditor representing the maximum misstatement in the population that the auditor is willing to accept and still conclude the audit objective has been achieved. It is typically set at or below performance materiality. Choice B is incorrect because the expected misstatement is a separate concept used to determine sample size, not the maximum acceptable amount.', 'easy', 1),

-- Q27: easy / L2 — Apply the distinction between error and fraud misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Bayshore Electronics, the engagement team discovers a $14,000 overstatement in travel expenses. Investigation reveals the accounting clerk transposed two digits when entering an invoice amount, recording $41,000 instead of $14,000. Under auditing standards, this misstatement is best classified as:', '["A fraud because the financial statements contain a material overstatement", "An irregularity because the expense account was misstated", "An error because the misstatement resulted from an unintentional mistake", "A judgmental misstatement because it involved data entry judgment"]'::jsonb, 2, 'Under AU-C 240.02, misstatements can arise from either fraud or error. Fraud involves intentional acts, while errors are unintentional mistakes such as clerical errors, transpositions, or misapplications of accounting policies. A digit transposition by a clerk is a classic unintentional error. Choice D is incorrect because judgmental misstatements arise from differences in management''s estimates or accounting policy judgments, not from data entry mistakes.', 'easy', 2),

-- Q28: medium / L2 — Apply the turnaround effect of prior-period misstatements
(1, 'Misstatements and Control Deficiencies', 'During the 2025 audit of Golden Gate Logistics, the auditor notes that a $30,000 revenue item was improperly recorded in 2024 instead of 2025. The misstatement was not corrected in the 2024 financial statements. When evaluating the effect on the 2025 financial statements, the auditor should recognize that this misstatement causes:', '["A $30,000 overstatement of 2025 revenue only", "No effect on 2025 because the misstatement originated in the prior period", "A $60,000 combined misstatement across both periods", "A $30,000 understatement of 2025 revenue and an overstatement of 2025 opening retained earnings"]'::jsonb, 3, 'Under AU-C 450.A8, when a prior-period cutoff misstatement is not corrected, it reverses in the current period. Revenue recorded in 2024 that belongs in 2025 means 2025 revenue is understated by $30,000, while retained earnings brought forward from 2024 is overstated by $30,000. Both effects must be considered. Choice B is incorrect because uncorrected prior-period misstatements carry forward and affect the current period''s financial statements through opening balances and reversal effects.', 'medium', 2),

-- Q29: medium / L2 — Apply the requirement to accumulate misstatements across all audit phases
(1, 'Misstatements and Control Deficiencies', 'Henderson & Park LLP is auditing Silverline Corp. for the year ended December 31, 2025. During interim testing in October, the team identifies $8,500 in misstatements. During year-end fieldwork in February 2026, the team finds an additional $11,200 in misstatements. Under AU-C 450, the auditor must:', '["Evaluate only the $11,200 from year-end testing since interim misstatements may have been corrected", "Maintain a cumulative schedule of all $19,700 in identified misstatements from both phases of the audit", "Communicate the $8,500 separately from the $11,200 because they were identified in different audit phases", "Disregard the interim misstatements if they are below performance materiality"]'::jsonb, 1, 'Under AU-C 450.05, the auditor is required to accumulate all misstatements identified during the audit, other than those that are clearly trivial. This includes misstatements from all phases of the audit—interim and year-end. The cumulative total is then evaluated against materiality. Choice A is incorrect because the auditor cannot assume interim misstatements were corrected without verifying; all identified misstatements must remain on the summary until confirmed as corrected.', 'medium', 2),

-- Q30: easy / L1 — Definition of a design deficiency
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what characterizes a design deficiency in internal control?', '["A control that was properly designed but employees fail to execute it correctly", "A control that is too costly for the entity to implement effectively", "A necessary control is missing, or an existing control is not designed to meet its objective", "A control that operates effectively but has not been documented in writing"]'::jsonb, 2, 'Under AU-C 265.A3, a design deficiency exists when a necessary control is missing or when an existing control is not properly designed to meet the control objective, such that even if the control operates as designed, it would not prevent or detect misstatements on a timely basis. Choice A is incorrect because a properly designed control that is not executed correctly represents an operating deficiency, not a design deficiency.', 'easy', 1)
;

COMMIT;
